fn array_sum(a: Vec<i32>, b: Vec<i32>) -> Vec<i32> {
    // Since a and b have the same length by assumption, we can zip them
    // and sum element‐wise.
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x + y)
     .collect()
}

